  VALUES ('sample-faq-6', 'faqs', NULL, '{"id":"sample-faq-6","question":"What happens after I order?","answer":"1. We call you to confirm your order and arrange payment.\n2. We prepare your equipment.\n3. Your order goes out for delivery.\n4. When your order includes installation, our engineers install and test the system after delivery.\nYou can call us at any step.","category":"Ordering","sortOrder":6,"isActive":true,"sample":true,"createdAt":"2026-09-17T08:00:05.000Z","updatedAt":"2026-09-17T08:00:05.000Z"}', 1, 6, '2026-09-17T08:00:05.000Z', '2026-09-17T08:00:05.000Z')
