  VALUES ('sample-faq-8', 'faqs', NULL, '{"id":"sample-faq-8","question":"How do I choose a package size?","answer":"Use our solar calculator: pick the appliances you want to power and it estimates the inverter size, batteries and panels you need, then shows matching packages. If you''re not sure, talk to an engineer and we''ll recommend a size before installation.","category":"Ordering","sortOrder":8,"isActive":true,"sample":true,"createdAt":"2026-09-17T08:00:07.000Z","updatedAt":"2026-09-17T08:00:07.000Z"}', 1, 8, '2026-09-17T08:00:07.000Z', '2026-09-17T08:00:07.000Z')
