    OR (COALESCE(json_extract(data, '$.financing.enabled'), 0) != 1 AND COALESCE(json_array_length(data, '$.financing.termsMonths'), 0) = 0 AND json_extract(data, '$.financing.depositPercent') IS NULL)
  );
UPDATE records SET data = json_set(data, '$.calculator', json('{"enabled":true,"appliances":[{"key":"fan","label":"Fan","watts":75,"defaultHours":8,"defaultQuantity":2},{"key":"led-bulb","label":"LED bulb","watts":10,"defaultHours":6,"defaultQuantity":6},{"key":"tv","label":"TV","watts":120,"defaultHours":5,"defaultQuantity":1},{"key":"decoder","label":"Decoder","watts":25,"defaultHours":5,"defaultQuantity":1},{"key":"laptop","label":"Laptop","watts":65,"defaultHours":4,"defaultQuantity":1},{"key":"phone-charging","label":"Phone charging","watts":10,"defaultHours":3,"defaultQuantity":3},{"key":"fridge","label":"Fridge","watts":150,"defaultHours":12,"defaultQuantity":1},{"key":"freezer","label":"Freezer","watts":200,"defaultHours":12,"defaultQuantity":0},{"key":"washing-machine","label":"Washing machine","watts":500,"defaultHours":1,"defaultQuantity":0},{"key":"microwave","label":"Microwave","watts":1000,"defaultHours":0.5,"defaultQuantity":0},{"key":"ac-1hp","label":"1hp air conditioner","watts":900,"defaultHours":4,"defaultQuantity":0},{"key":"pumping-machine","label":"Pumping machine","watts":750,"defaultHours":0.5,"defaultQuantity":0}],"inverterHeadroomPercent":25,"batteryDepthOfDischargePercent":80,"batteryVoltage":48,"panelWatts":550,"peakSunHours":4.5,"generator":{"fuelPricePerLitre":1000,"litresPerKvaHour":0.25,"maintenancePerMonth":20000},"sample":true}'))
